from __future__ import annotations
import hashlib, json, os, tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any

class ShadowInvariantError(RuntimeError):
    pass

class ImmutableRawArchive:
    def __init__(self, root: Path): self.root=Path(root)
    def store_bytes(self,payload:bytes,*,source:str,received_at:str,content_type:str|None=None)->dict[str,Any]:
        if not isinstance(payload,(bytes,bytearray)): raise ShadowInvariantError('payload must be bytes')
        raw=bytes(payload); digest=hashlib.sha256(raw).hexdigest()
        obj=self.root/'objects'/digest[:2]/f'{digest}.bin'; manifest=self.root/'manifests'/f'{digest}.json'
        obj.parent.mkdir(parents=True,exist_ok=True); manifest.parent.mkdir(parents=True,exist_ok=True)
        if obj.exists():
            if obj.read_bytes()!=raw: raise ShadowInvariantError('hash-addressed object mutation detected')
        else:
            fd,tmp=tempfile.mkstemp(prefix=f'.{digest}.',suffix='.tmp',dir=str(obj.parent))
            try:
                with os.fdopen(fd,'wb') as h: h.write(raw); h.flush(); os.fsync(h.fileno())
                os.replace(tmp,obj)
            finally:
                try: os.unlink(tmp)
                except FileNotFoundError: pass
        rec={'schema':'HENGELTJE_IMMUTABLE_RAW_V1','sha256':digest,'bytes':len(raw),'source':source,'received_at':received_at,'content_type':content_type,'object_name':obj.name}
        enc=(json.dumps(rec,sort_keys=True,separators=(',',':'))+'\n').encode()
        if manifest.exists():
            if manifest.read_bytes()!=enc: raise ShadowInvariantError('manifest mutation detected for existing raw object')
        else:
            fd,tmp=tempfile.mkstemp(prefix=f'.{digest}.',suffix='.tmp',dir=str(manifest.parent))
            try:
                with os.fdopen(fd,'wb') as h: h.write(enc); h.flush(); os.fsync(h.fileno())
                os.replace(tmp,manifest)
            finally:
                try: os.unlink(tmp)
                except FileNotFoundError: pass
        return rec

@dataclass(frozen=True)
class VirtualOrder:
    ticker:str; side:str; price_cents:int; size_contracts:int; t_minus_minutes:int; created_at:str
    def __post_init__(self):
        if self.side not in {'YES','NO'}: raise ShadowInvariantError('invalid side')
        if not 1<=self.price_cents<=99: raise ShadowInvariantError('invalid passive price')
        if self.size_contracts<=0: raise ShadowInvariantError('invalid size')

@dataclass
class QueueTracker:
    order:VirtualOrder; queue_ahead:int=0; proven_fill:int=0; last_sequence:int|None=None; status:str='AWAITING_SNAPSHOT'
    @property
    def remaining(self): return max(0,self.order.size_contracts-self.proven_fill)
    def snapshot(self,*,sequence:int,displayed_qty_at_price:int):
        if sequence<0 or displayed_qty_at_price<0: raise ShadowInvariantError('invalid snapshot')
        if self.last_sequence is not None: raise ShadowInvariantError('snapshot reset forbidden for active order')
        self.last_sequence=sequence; self.queue_ahead=displayed_qty_at_price; self.status='ACTIVE'
    def event(self,*,sequence:int,executed_qty:int=0,cancelled_qty:int=0,touched:bool=False):
        if self.status!='ACTIVE': return
        if self.last_sequence is None or sequence!=self.last_sequence+1: self.status='UNPROVEN_FILL'; return
        if executed_qty<0 or cancelled_qty<0: raise ShadowInvariantError('negative event quantity')
        self.last_sequence=sequence
        if executed_qty==0: return
        consumed=min(self.queue_ahead,executed_qty); self.queue_ahead-=consumed; residual=executed_qty-consumed
        if residual>0 and self.remaining>0: self.proven_fill+=min(self.remaining,residual)
    def reconnect(self,*,continuity_proven:bool=False):
        if self.status=='ACTIVE' and not continuity_proven: self.status='UNPROVEN_FILL'
    def restart(self,*,continuity_proven:bool=False):
        if self.status=='ACTIVE' and not continuity_proven: self.status='UNPROVEN_RESTART'
    def primary_filled_quantity(self):
        return 0 if self.status in {'UNPROVEN_FILL','UNPROVEN_RESTART'} else self.proven_fill
